// Recibe la lista de adjuntos que INYECTA beckham_bot (el agente no puede
// inventarse una URL) y decide por que rama va: PDF, imagen o nada legible.
// Se coge el ULTIMO adjunto, que es el que el cliente acaba de mandar.
//
// FORMATOS REALES (diseno del 6/08): la mayoria PDF (contratos y altas de la SS),
// PNG o foto para DNI/NIE/pasaporte, y la AUTORIZACION DE TAXDOWN en DOCX o PDF
// segun como la suba el cliente. El DOCX NO se puede leer con la Responses API y
// NO se intenta: se declara no legible y se guarda igual, porque su contenido es
// la plantilla propia de TaxDown y ya se conoce.
const j = $input.first().json;
let lista = [];
try {
  const crudo = j.adjuntos_json;
  lista = typeof crudo === 'string' ? JSON.parse(crudo || '[]') : (Array.isArray(crudo) ? crudo : []);
} catch (e) {
  lista = [];
}
if (!Array.isArray(lista)) lista = [];

const limpias = [];
for (const a of lista) {
  const nombre = String((a && (a.name || a.nombre)) || '').trim();
  const url = String((a && a.url) || '').trim();
  if (url) limpias.push({ nombre, url });
}

const casa = function (re) { return function (x) { return re.test(x.nombre) || re.test(x.url); }; };
const esPdf = casa(/\.pdf(\?|$)/i);
const esImg = casa(/\.(png|jpe?g|gif|webp|bmp|heic)(\?|$)/i);
const esDocx = casa(/\.(docx?|odt|rtf)(\?|$)/i);

const pdfs = limpias.filter(esPdf);
const imgs = limpias.filter(esImg);
const docs = limpias.filter(function (x) { return !esPdf(x) && !esImg(x) && esDocx(x); });
const otros = limpias.filter(function (x) { return !esPdf(x) && !esImg(x) && !esDocx(x); });

// Prioridad: PDF primero, que es como llega la mayoria.
const elegido = pdfs.length ? pdfs[pdfs.length - 1] : (imgs.length ? imgs[imgs.length - 1] : null);

return [{ json: {
  es_pdf: pdfs.length > 0,
  es_imagen: pdfs.length === 0 && imgs.length > 0,
  hay_algo: elegido !== null,
  url: elegido ? elegido.url : '',
  nombre: elegido ? elegido.nombre : '',
  cuantos_pdf: pdfs.length,
  cuantas_imagenes: imgs.length,
  docx: docs.map(function (x) { return x.nombre || x.url; }).join(', '),
  no_soportados: otros.map(function (x) { return x.nombre || x.url; }).join(', '),
  pregunta: String(j.pregunta || '').trim() || 'Identifica el documento y extrae solo lo que no tengamos.'
} }];

// El nodo Agent de beckham_bot solo entiende TEXTO: aqui se aplana la respuesta
// del modelo a un unico campo `analisis`, y se le anade de que fichero se trata.
const j = $input.first().json;
let texto = '';
if (typeof j.content === 'string') texto = j.content;
else if (typeof j.output_text === 'string') texto = j.output_text;
else if (typeof j.text === 'string') texto = j.text;
else if (j.message && typeof j.message.content === 'string') texto = j.message.content;
else if (typeof j.analisis === 'string') texto = j.analisis;
else texto = JSON.stringify(j);

const e = $('Elegir_Documento').first().json;
let cabecera = e.nombre ? ('Fichero leido: ' + e.nombre + '\n\n') : '';
let cola = '';
if (e.docx) cola += '\n\nAdemas he recibido ' + e.docx + ' (documento de Word): no puedo leer su contenido, pero se guarda igual y no hay que pedirlo otra vez.';
if (e.no_soportados) cola += '\n\nOtros ficheros recibidos que NO he podido leer: ' + e.no_soportados + '.';
if (e.cuantos_pdf > 1 || e.cuantas_imagenes > 1) cola += '\n\nAVISO: habia mas de un fichero legible y solo he leido el ultimo.';

return [{ json: { analisis: (cabecera + String(texto).trim() + cola).trim(), leido: true, fichero: e.nombre } }];
